content:
.card {
  border-radius: 12px;
  border-color: #e8ebe7;
}

.card:focus-visible {
  outline: 2px solid #183c30;
  outline-offset: -2px;
}

.media {
  aspect-ratio: 1;
  background: #f6f7f5;
}

.image {
  padding: 34px 10px 12px;
  mix-blend-mode: multiply;
}

.info {
  padding: 14px 12px 12px;
}

.title {
  min-height: 3em;
  line-height: 1.5;
  font-size: 13px;
}

.prices {
  margin-top: auto;
  padding-top: 12px;
  border-top: 0;
  min-height: 40px;
}

.action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 46px;
  margin-top: 8px;
  padding: 12px 0 2px;
  border-top: 1px solid #e8ebe7;
  background: transparent;
  color: #171717;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -.01em;
  transition: color 180ms ease;
}

.actionIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform 180ms ease;
}

@media (hover: hover) and (pointer: fine) {
  .card:hover .action { color: #24543f; }
  .card:hover .actionIcon { transform: translateX(2px); }
}

.card:focus-visible .action { text-decoration: underline; text-underline-offset: 4px; }

@media (min-width: 640px) {
  .info { padding: 16px; }
  .title { font-size: 14px; }
  .image { padding: 38px 16px 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .card, .card * { transition: none !important; }
}
